/// Compile-time generation of Alioth inheritance graph from isahl_meta.meta_collections.
///
/// Queries `config.inherits` for every table and emits `add_inheritance(table, parents)` calls.
/// Requires `DATABASE_URL` env var. Build fails with a clear message if unset or if the query
/// returns no rows — a stale hardcoded graph is worse than a broken build.
use std::process::Command;

fn main() {
    // BUILD_DATABASE_URL 优先：构建元数据源与运行时数据源分离
    let db_url = std::env::var("BUILD_DATABASE_URL")
        .or_else(|_| std::env::var("DATABASE_URL"))
        .unwrap_or_else(|_| "postgres://localhost:5432/aliothstudio_dev".to_string());

    let out_dir = std::env::var("OUT_DIR").expect("OUT_DIR not set by cargo");

    let output = Command::new("psql")
        .arg(&db_url)
        .arg("-tA")
        .arg("-F")
        .arg("\t")
        .arg("-c")
        .arg(
            "SELECT table_name, COALESCE(config->>'inherits', '[]') \
             FROM isahl_meta.meta_collections \
             WHERE table_name IS NOT NULL \
             ORDER BY table_name",
        )
        .output()
        .unwrap_or_else(|e| {
            panic!(
                "Failed to run psql. Is PostgreSQL installed and `DATABASE_URL` set?\n\
                 DATABASE_URL={}\nError: {}",
                db_url, e
            )
        });

    // 容错（用户 reset 后 isahl_meta.meta_collections 可能缺失/空——如 WZ dev 无 Meta 平台）：
    // 查询失败或 0 行 → 生成空继承图（WARN），不再 panic 阻断构建。
    if !output.status.success() || String::from_utf8_lossy(&output.stdout).trim().is_empty() {
        let stderr = String::from_utf8_lossy(&output.stderr);
        eprintln!(
            "[trigger-registry] WARN: isahl_meta.meta_collections 查询失败或为空（{}），
             生成空继承图——若需完整继承，请初始化 Meta 平台（isahl_meta.meta_collections）。
             stderr: {}",
            db_url, stderr
        );
        let empty = String::from(
            "// Auto-generated by build.rs — DO NOT EDIT. (空图：meta_collections 缺失)\n\
             pub fn load_generated_inheritance(_graph: &mut crate::inheritance::InheritanceGraph) {}\n",
        );
        let dest_path = std::path::Path::new(&out_dir).join("inheritance_graph.rs");
        std::fs::write(&dest_path, &empty)
            .unwrap_or_else(|e| panic!("Failed to write empty inheritance graph: {}", e));
        println!("cargo:rerun-if-env-changed=BUILD_DATABASE_URL");
        return;
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let lines: Vec<&str> = stdout.lines().filter(|l| !l.is_empty()).collect();
    // Generate Rust source with all add_inheritance calls
    let mut code = String::from(
        "// Auto-generated by build.rs — DO NOT EDIT.\n\
         // Regenerate by running `cargo build` with DATABASE_URL set.\n\n\
         pub fn load_generated_inheritance(graph: &mut crate::inheritance::InheritanceGraph) {\n",
    );

    for line in &lines {
        let trimmed = line.trim();
        if trimmed.is_empty() {
            continue;
        }
        // Format: table_name<TAB>["parent1","parent2"] or []
        let parts: Vec<&str> = trimmed.splitn(2, '\t').collect();
        if parts.len() < 2 {
            continue;
        }
        let table_name = parts[0].trim();

        // Parse the JSON array of parent table names
        let inherits_json = parts[1].trim();
        // Simple parsing: extract strings between quotes
        let parents: Vec<&str> = inherits_json
            .trim_start_matches('[')
            .trim_end_matches(']')
            .split(',')
            .filter_map(|s| {
                let s = s.trim().trim_matches('"');
                if s.is_empty() {
                    None
                } else {
                    Some(s)
                }
            })
            .collect();

        if parents.is_empty() {
            code.push_str(&format!(
                "    graph.add_inheritance(\"{}\", Vec::<&str>::new());\n",
                table_name
            ));
        } else {
            let parents_str = parents
                .iter()
                .map(|p| format!("\"{}\"", p))
                .collect::<Vec<_>>()
                .join(", ");
            code.push_str(&format!(
                "    graph.add_inheritance(\"{}\", vec![{}]);\n",
                table_name, parents_str
            ));
        }
    }

    code.push_str("}\n");

    let dest_path = std::path::Path::new(&out_dir).join("inheritance_graph.rs");
    std::fs::write(&dest_path, &code).unwrap_or_else(|e| {
        panic!(
            "Failed to write generated inheritance graph to {:?}: {}",
            dest_path, e
        );
    });

    println!("cargo:rerun-if-changed=build.rs");
    println!("cargo:rerun-if-env-changed=DATABASE_URL");
    println!("cargo:rerun-if-env-changed=BUILD_DATABASE_URL");
    eprintln!(
        "Generated inheritance graph with {} tables → {}",
        lines.len(),
        dest_path.display()
    );
}
